#include <stdexcept>

class IntArray {
public:
    explicit IntArray(int n, int init = 0) : n_(n), data_(new int[n]) {
        std::fill(data_, data_ + n_, init);
    }
    IntArray(const IntArray& o) : n_(o.n_), data_(new int[o.n_]) {
        std::copy(o.data_, o.data_ + o.n_, data_);
    }
