        data_ = fresh;
        n_ = o.n_;
        return *this;
    }
    ~IntArray() { delete[] data_; }

    int& operator[](int i) { return data_[i]; }          // 不检查
    const int& operator[](int i) const { return data_[i]; }

    int& at(int i) {
        check(i);
        return data_[i];
    }
    const int& at(int i) const {
        check(i);
        return data_[i];
    }
    int size() const { return n_; }

private:
